// FinishPasskeySignIn operation middleware
func (siw *ServerInterfaceWrapper) FinishPasskeySignIn(w http.ResponseWriter, r *http.Request) {

	var err error
	_ = err

	// Parameter object where we will unmarshal all parameters from the context
	var params FinishPasskeySignInParams

	{
		var cookie *http.Cookie

		if cookie, err = r.Cookie("__Host-glossa_webauthn"); err == nil {
			var value CeremonyCookie
			err = runtime.BindStyledParameterWithOptions("simple", "__Host-glossa_webauthn", cookie.Value, &value, runtime.BindStyledParameterOptions{ParamLocation: runtime.ParamLocationCookie, Explode: true, Required: false, Type: "string", Format: ""})
			if err != nil {
				siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "__Host-glossa_webauthn", Err: err})
				return
			}
			params.UnderscoreUnderscoreHostGlossaWebauthn = &value

		}
	}

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.FinishPasskeySignIn(w, r, params)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

